<script setup>
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useSafeLabDemoStore } from '@/shared/application/stores/demo.store'
const route = useRoute(); const router = useRouter(); const demo = useSafeLabDemoStore()
const incident = computed(() => demo.incidents.find((item) => item.id === route.params.id) || demo.incidents[0])
</script>
<template><section class="page"><button class="btn" @click="router.back()"><i class="pi pi-arrow-left"></i> Back</button><article v-if="incident" class="card"><div class="card-header"><div><p class="eyebrow">{{ incident.code }} · {{ incident.severity }}</p><h1>{{ incident.title }}</h1><p>{{ incident.description }}</p></div><span :class="['status-pill', incident.status]">{{ incident.status }}</span></div><div class="grid-4"><div class="pair-box"><span>Assigned to</span><strong>{{ incident.assignedTo }}</strong></div><div class="pair-box"><span>Related sensor</span><strong>{{ incident.relatedSensorId }}</strong></div><div class="pair-box"><span>Related asset</span><strong>{{ incident.relatedAssetId }}</strong></div><div class="pair-box"><span>Evidence</span><strong>{{ incident.evidence }}</strong></div></div><article class="card" style="margin-top:18px; box-shadow:none;"><h2>Corrective action</h2><p>Attach evidence, investigate the cause and close the incident when controls are validated.</p></article><article class="card" style="margin-top:18px; box-shadow:none;"><h2>Incident timeline</h2><div class="item-list"><div class="list-row"><span><strong>Incident created</strong><small>{{ new Date(incident.createdAt).toLocaleString() }}</small></span></div><div class="list-row"><span><strong>Last update</strong><small>{{ new Date(incident.updatedAt).toLocaleString() }}</small></span></div></div></article><div class="modal-footer"><button class="btn primary" @click="demo.updateIncidentStatus(incident.id,'investigating')">Start investigation</button><button class="btn success" @click="demo.updateIncidentStatus(incident.id,'resolved')">Mark as resolved</button><button class="btn danger" @click="demo.updateIncidentStatus(incident.id,'closed')">Close incident</button><button class="btn" @click="router.push(`/incident-management/incident-report/${incident.id}`)">View report</button></div></article></section></template>
